import com.jh.friendgames.GameCatalog;
public class CatalogTest {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public static void main(String[] a){check(GameCatalog.ROOM_URL.endsWith("/club/"),"single shared-room entry");check(GameCatalog.isAllowed(GameCatalog.ROOM_URL),"entry in app");check(GameCatalog.isAllowed("https://ten-half-duel-jh.onrender.com/club-game/card/?epoch=1"),"game frame");check(GameCatalog.isAllowed("https://ten-half-duel-jh.onrender.com:443/club/"),"https port");for(String u:new String[]{"http://ten-half-duel-jh.onrender.com/club/","https://ten-half-duel-jh.onrender.com.evil.test","https://user@ten-half-duel-jh.onrender.com","https://ten-half-duel-jh.onrender.com:1234","file:///etc/passwd","javascript:alert(1)"})check(!GameCatalog.isAllowed(u),"reject unsafe navigation");check(GameCatalog.isDownload("https://ten-half-duel-jh.onrender.com/club.apk?v=2"),"apk external");check(!GameCatalog.isDownload(GameCatalog.ROOM_URL),"lobby remains in app");System.out.println("Unified-room navigation tests passed.");}
}
